layer.css:
[data-ryt="pitch"] { color: rgb(73, 80, 87); background-color: rgb(233, 236, 239); border-left: 8px solid rgb(52, 58, 64); border-radius: 0px; font-family: "Open Sans"; font-size: 20px; font-weight: 400; font-style: italic; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(73, 80, 87); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 25.344px; padding-right: 30px; padding-bottom: 25.344px; padding-left: 75px; transition: all; border-top: none; border-right: none; border-bottom: none; position: relative }
article[data-ryt="rec-card"] { border-bottom: 1px solid rgb(222, 226, 230); border-radius: 0px; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="footer"] { color: var(--ryt-text); border-top: 2px solid rgb(222, 226, 230); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 500; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { background-color: rgba(0, 0, 0, 0.25); border-radius: 0px; box-shadow: rgba(0, 0, 0, 0.25) -1px 0px 0px 0px inset; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; color: var(--ryt-text) }
[data-ryt="nav"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 17.6px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 15.4px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 17.6px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]:hover { color: rgb(0, 86, 179); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: rgb(0, 86, 179); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="nav"] a:hover { color: rgb(0, 86, 179); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="brand"]:hover { color: rgb(0, 86, 179); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: rgb(0, 86, 179); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="pitch"]::before { content: "“"; display: block; position: absolute; width: 28.1406px; height: 135.172px; color: rgb(52, 58, 64); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: Arial; font-size: 84.48px; font-weight: 400; font-style: italic; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(52, 58, 64); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: rgb(52, 58, 64); top: -10px; left: 10px }
[data-ryt="pitch"]::after { content: ""; display: inline; color: rgb(73, 80, 87); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: "Open Sans"; font-size: 21.12px; font-weight: 400; font-style: italic; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(73, 80, 87); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: rgb(73, 80, 87) }
